function renderSport(){data.sports ||= [];data.routines ||= [];const items=sportDateItems();const todayItems=(data.sports||[]).filter(x=>x.date===iso(today));const todayMinutes=todayItems.reduce((n,x)=>n+(Number(x.duration)||0),0);if($('#sportSelectedDate'))$('#sportSelectedDate').textContent=selected===iso(today)?'Sesiones de hoy':pretty(selected,{day:'numeric',month:'short'});if($('#sportTodaySessions'))$('#sportTodaySessions').textContent=String(todayItems.length);if($('#sportTodayTime'))$('#sportTodayTime').textContent=todayMinutes>=60?`${Math.floor(todayMinutes/60)} h ${todayMinutes%60} min`:`${todayMinutes} min`;$('#sportDayCount').textContent=`${items.length} ${items.length===1?'sesión':'sesiones'}`;$('#sportSessionList').innerHTML=items.length?items.map(x=>`<article class="card sport-session"><div class="sport-session-head"><span class="shift-badge">${escapeHTML(x.type)}</span><button class="delete-expense" type="button" data-sport-delete="${escapeHTML(x.id)}" aria-label="Eliminar sesión">×</button></div><h3>${escapeHTML(x.title||x.type)}</h3><div class="sport-metrics">${x.duration?`<span>◷ ${Number(x.duration)} min</span>`:''}${x.distance?`<span>↗ ${Number(x.distance)} km</span>`:''}${x.meters?`<span>≈ ${Number(x.meters)} m</span>`:''}</div>${x.details?`<p>${escapeHTML(x.details).replace(/\n/g,'<br>')}</p>`:''}${x.notes?`<small>${escapeHTML(x.notes)}</small>`:''}</article>`).join(''):'<div class="card empty-expenses">No hay actividad deportiva registrada para este día.</div>';$$('[data-sport-delete]').forEach(b=>b.addEventListener('click',()=>{if(!confirm('¿Eliminar esta sesión deportiva?'))return;data.sports=data.sports.filter(x=>x.id!==b.dataset.sportDelete);save();renderSport();renderDailySummary()}));$('#routineList').innerHTML=data.routines.length?data.routines.map((r,i)=>`<article class="routine-row"><div><strong>${escapeHTML(r.name)}</strong><small>${escapeHTML(r.details||'Sin ejercicios añadidos')}</small></div><button class="secondary-btn" type="button" data-routine-use="${i}">Usar</button><button class="delete-expense" type="button" data-routine-delete="${i}" aria-label="Eliminar rutina">×</button></article>`).join(''):'<p class="muted">Todavía no has guardado rutinas.</p>';$$('[data-routine-use]').forEach(b=>b.addEventListener('click',()=>{const r=data.routines[+b.dataset.routineUse];$('#sportType').value='Gimnasio';$('#sportTitle').value=r.name;$('#sportDetails').value=r.details;toast('Rutina cargada. Registra la sesión cuando termines.')}));$$('[data-routine-delete]').forEach(b=>b.addEventListener('click',()=>{data.routines.splice(+b.dataset.routineDelete,1);save();renderSport()}));renderSportStats();}
function renderSportStats(){const year=Number($('#sportYear')?.value)||sportYear;const records=(data.sports||[]).filter(x=>sportPeriod==='year'?x.date?.startsWith(String(year)):x.date?.startsWith(selected.slice(0,7)));const minutes=records.reduce((a,x)=>a+(Number(x.duration)||0),0),km=records.reduce((a,x)=>a+(Number(x.distance)||0),0),meters=records.reduce((a,x)=>a+(Number(x.meters)||0),0);const types={};records.forEach(x=>types[x.type]=(types[x.type]||0)+1);$('#sportStats').innerHTML=`<div class="stat-card"><span>Sesiones</span><strong>${records.length}</strong></div><div class="stat-card"><span>Tiempo activo</span><strong>${Math.floor(minutes/60)} h ${minutes%60} min</strong></div><div class="stat-card"><span>Distancia total</span><strong>${km.toLocaleString('es-ES',{maximumFractionDigits:2})} km</strong></div><div class="stat-card"><span>Metros nadados</span><strong>${meters.toLocaleString('es-ES')} m</strong></div><div class="card sport-type-stats">${Object.keys(types).length?Object.entries(types).map(([k,v])=>`<div><span>${escapeHTML(k)}</span><strong>${v}</strong></div>`).join(''):'<p class="muted">Registra actividades para ver tus estadísticas.</p>'}</div>`;$$('[data-sport-period]').forEach(b=>b.classList.toggle('active',b.dataset.sportPeriod===sportPeriod));}
function initSport(){setupYearSelect('#sportYear',sportYear,y=>{sportYear=y;renderSportStats()});const sportIcons={'Gimnasio':'🏋️','Correr':'🏃','Caminar':'🚶','Bicicleta':'🚴','Monte / senderismo':'⛰️','Piscina':'🏊','Otro':'＋'};const sportHeadings={'Gimnasio':'Entrenamiento de gimnasio','Correr':'Registrar carrera','Caminar':'Registrar caminata','Bicicleta':'Registrar salida en bicicleta','Monte / senderismo':'Registrar ruta de monte','Piscina':'Registrar sesión de piscina','Otro':'Registrar otro deporte'};function selectSport(type){$('#sportType').value=type;$$('[data-sport-choice]').forEach(b=>b.classList.toggle('selected',b.dataset.sportChoice===type));if($('#sportFormHeading'))$('#sportFormHeading').textContent=sportHeadings[type]||'Registrar actividad';if($('#sportFormSymbol'))$('#sportFormSymbol').textContent=sportIcons[type]||'＋';if($('#sportDetailsHint'))$('#sportDetailsHint').textContent=type==='Gimnasio'?'En el gimnasio, apunta ejercicios, series, repeticiones y pesos.':type==='Piscina'?'Puedes describir el estilo, los largos o la estructura del entrenamiento.':'Añade detalles del recorrido, la intensidad o cómo te has sentido.';document.querySelector('.sport-meters-field')?.classList.toggle('sport-meters-highlight',type==='Piscina')}$$('[data-sport-choice]').forEach(b=>b.addEventListener('click',()=>{selectSport(b.dataset.sportChoice);$('#sportEntryCard')?.scrollIntoView({behavior:'smooth',block:'start'})}));$('#sportType').addEventListener('change',()=>selectSport($('#sportType').value));$('#sportStartButton')?.addEventListener('click',()=>{$('#sportEntryCard')?.scrollIntoView({behavior:'smooth',block:'start'});$('#sportTitle')?.focus({preventScroll:true})});selectSport($('#sportType').value);$('#saveSport').addEventListener('click',()=>{const type=$('#sportType').value,title=$('#sportTitle').value.trim(),duration=Number($('#sportDuration').value)||0,distance=Number($('#sportDistance').value)||0,meters=Number($('#sportMeters').value)||0,details=$('#sportDetails').value.trim(),notes=$('#sportNotes').value.trim();if(!title&&!duration&&!distance&&!meters&&!details){toast('Añade el nombre o algún dato de la actividad.');return}data.sports ||= [];data.sports.push({id:Date.now().toString(36)+Math.random().toString(36).slice(2,7),date:selected,type,title:title||type,duration,distance,meters,details,notes});save();clearSportFields();renderSport();renderDailySummary();toast('Actividad deportiva guardada')});$('#clearSportForm').addEventListener('click',clearSportFields);$('#saveRoutine').addEventListener('click',()=>{const name=$('#routineName').value.trim(),details=$('#routineDetails').value.trim();if(!name){toast('Escribe el nombre de la rutina.');return}data.routines ||= [];data.routines.push({name,details});save();$('#routineName').value='';$('#routineDetails').value='';renderSport();toast('Rutina guardada')});$$('[data-sport-period]').forEach(b=>b.addEventListener('click',()=>{sportPeriod=b.dataset.sportPeriod;renderSportStats()}));}
function initTheme(){let theme='light';try{theme=localStorage.getItem('toty-planner-theme')||'light'}catch{}applyTheme(theme);const btn=$('#themeToggle');if(btn)btn.addEventListener('click',()=>{const next=document.documentElement.dataset.theme==='dark'?'light':'dark';applyTheme(next);try{localStorage.setItem('toty-planner-theme',next)}catch{};});}
function openTab(tab){$$('.tab').forEach(x=>x.classList.toggle('active',x.dataset.tab===tab));$$('.view').forEach(x=>x.classList.toggle('active',x.id===tab));window.scrollTo({top:0,behavior:'smooth'});}
function renderCalendar(){const year=viewMonth.getFullYear(),month=viewMonth.getMonth();$('#monthTitle').textContent=viewMonth.toLocaleDateString('es-ES',{month:'long',year:'numeric'});const first=(new Date(year,month,1).getDay()+6)%7;const count=new Date(year,month+1,0).getDate();const prevCount=new Date(year,month,0).getDate();let html='';for(let i=0;i<42;i++){let n=i-first+1, d, outside=false;if(n<1){d=new Date(year,month-1,prevCount+n);outside=true}else if(n>count){d=new Date(year,month+1,n-count);outside=true}else d=new Date(year,month,n);const key=iso(d);html+=`<button class="calendar-day${outside?' outside':''}${key===iso(today)?' today':''}${key===selected?' selected':''}" data-date="${key}" aria-label="${escapeHTML(pretty(key))}">${d.getDate()}</button>`}$('#calendarGrid').innerHTML=html;$('#calendarGrid').querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>selectDate(b.dataset.date)))}
function selectDate(date){selected=date;viewMonth=new Date(date+'T12:00:00');workViewMonth=new Date(date+'T12:00:00');renderAll()}
function renderDay(){let d=dayData();$('#todayLabel').textContent=selected===iso(today)?'TU PLAN PARA HOY':'TU PLAN PARA';$('#dayTitle').textContent=pretty(selected);$('#priorityList').innerHTML=d.priorities.map((v,i)=>`<div class="priority-row"><input type="checkbox" data-check="${i}" ${d.checks[i]?'checked':''} aria-label="Completar tarea ${i+1}"><div class="task-fields"><input type="text" data-priority="${i}" value="${escapeHTML(v)}" placeholder="Tarea ${i+1}…" aria-label="Tarea ${i+1}"><label class="task-time-label">Hora (opcional)<input type="time" data-task-time="${i}" value="${escapeHTML(d.taskTimes[i]||'')}" aria-label="Hora de la tarea ${i+1}"></label></div><button class="delete-task" data-task-del="${i}" type="button" aria-label="Eliminar tarea ${i+1}" title="Eliminar tarea">×</button></div>`).join('');$$('[data-check]').forEach(el=>el.addEventListener('change',()=>{d.checks[+el.dataset.check]=el.checked;save();renderStats();renderUnifiedAgenda()}));$$('[data-priority]').forEach(el=>el.addEventListener('input',()=>{d.priorities[+el.dataset.priority]=el.value;save();renderUnifiedAgenda()}));$$('[data-task-time]').forEach(el=>el.addEventListener('change',()=>{d.taskTimes[+el.dataset.taskTime]=el.value;save();renderUnifiedAgenda()}));$$('[data-task-del]').forEach(el=>el.addEventListener('click',()=>{const i=+el.dataset.taskDel;d.priorities.splice(i,1);d.checks.splice(i,1);d.taskTimes.splice(i,1);save();renderDay()}));$('#dailyNotes').value=d.notes;$('#quickNotes').value=d.quick;$('#workout').value=d.workout;$('#workoutFeeling').value=d.feeling;$('#workoutExtra').value=d.extra;$('#expenseDay').textContent=selected===iso(today)?'hoy':pretty(selected,{day:'numeric',month:'short'});renderHabits();renderExpenses();renderAppointments();renderStats();if($('#deporte'))renderSport()}
function appointmentId(){return 'appt-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8)}
function appointmentStatusLabel(status){return status==='done'?'Realizada':status==='cancelled'?'Cancelada':'Pendiente'}
function formatAppointmentDate(date){return pretty(date,{weekday:'short',day:'numeric',month:'short'})}
function renderAppointments(){
 data.appointments ||= [];
 const list=$('#appointmentList'); if(!list)return;
 const items=data.appointments.filter(a=>a.date<=selected&&(a.endDate||a.date)>=selected).sort((a,b)=>(a.start||'').localeCompare(b.start||''));
 list.innerHTML=items.length?items.map(a=>`<article class="appointment-card ${a.status==='done'?'appointment-done':''} ${a.status==='cancelled'?'appointment-cancelled':''}" data-appointment-id="${escapeHTML(a.id)}">
  <div class="appointment-time"><strong>${a.mode==='allDay'?'Todo el día':escapeHTML(a.start||'--:--')}</strong><span>${a.mode==='allDay'?'':a.mode==='24h'?'24 horas':a.endDate&&a.endDate!==a.date?`${escapeHTML(a.end||'')} · hasta ${escapeHTML(formatAppointmentDate(a.endDate))}`:escapeHTML(a.end||'')}</span></div>
  <div class="appointment-content"><div class="appointment-title-line"><h3>${escapeHTML(a.title||'Cita sin título')}</h3><span class="appointment-status status-${escapeHTML(a.status||'pending')}">${appointmentStatusLabel(a.status||'pending')}</span></div>
  ${a.location?`<p class="appointment-detail">⌖ ${escapeHTML(a.location)}</p>`:''}${a.notes?`<p class="appointment-notes">${escapeHTML(a.notes)}</p>`:''}<p class="appointment-detail">${Number(a.reminder)>0?'◷ Aviso '+(Number(a.reminder)===1440?'1 día':Number(a.reminder)===60?'1 hora':a.reminder+' min')+' antes':'Sin aviso previo'}</p>
  <div class="appointment-actions"><label class="appointment-status-select-label">Estado<select data-appointment-status="${escapeHTML(a.id)}"><option value="pending" ${(a.status||'pending')==='pending'?'selected':''}>Pendiente</option><option value="done" ${a.status==='done'?'selected':''}>Realizada</option><option value="cancelled" ${a.status==='cancelled'?'selected':''}>Cancelada</option></select></label><button class="delete-expense appointment-delete" type="button" data-appointment-delete="${escapeHTML(a.id)}" aria-label="Eliminar cita">×</button></div>
 </div></article>`).join(''):'<div class="empty-expenses appointment-empty">No tienes citas para este día. Pulsa «Añadir cita» para crear una.</div>';
 $$('[data-appointment-status]').forEach(el=>el.addEventListener('change',()=>{const a=data.appointments.find(x=>x.id===el.dataset.appointmentStatus);if(!a)return;a.status=el.value;save();renderAppointments();toast('Estado de la cita actualizado')}));
 $$('[data-appointment-delete]').forEach(el=>el.addEventListener('click',()=>{if(!confirm('¿Eliminar esta cita?'))return;data.appointments=data.appointments.filter(a=>a.id!==el.dataset.appointmentDelete);save();renderAppointments();toast('Cita eliminada')}));
 renderUnifiedAgenda();
}
function renderUnifiedAgenda(){const host=$('#dailyTimeline');if(!host)return;const d=dayData();const appointments=(data.appointments||[]).filter(a=>a.date<=selected&&(a.endDate||a.date)>=selected).map(a=>({kind:'appointment',time:a.mode==='allDay'?'Todo el día':a.start||'',end:a.mode==='24h'?'24 horas':a.endDate&&a.endDate!==a.date?`hasta ${formatAppointmentDate(a.endDate)}`:a.end||'',title:a.title||'Cita sin título',status:a.status||'pending',location:a.location||'',id:a.id}));const tasks=d.priorities.map((title,i)=>({kind:'task',time:(d.taskTimes||[])[i]||'',title:(title||'').trim(),done:!!d.checks[i],index:i})).filter(t=>t.title);const timed=[...appointments,...tasks].filter(x=>x.time).sort((a,b)=>a.time.localeCompare(b.time)||(a.kind==='appointment'?-1:1));const untimedTasks=tasks.filter(t=>!t.time);let html='';if(timed.length){html+=timed.map(item=>item.kind==='appointment'?`<div class="timeline-item ${item.status==='done'?'timeline-done':''} ${item.status==='cancelled'?'timeline-cancelled':''}"><div class="timeline-clock">${escapeHTML(item.time)}<small>${escapeHTML(item.end)}</small></div><div class="timeline-marker appointment-marker">◷</div><div class="timeline-content"><span class="timeline-kind">CITA · ${item.status==='done'?'REALIZADA':item.status==='cancelled'?'CANCELADA':'PENDIENTE'}</span><strong>${escapeHTML(item.title)}</strong>${item.location?`<small>${escapeHTML(item.location)}</small>`:''}</div></div>`:`<div class="timeline-item ${item.done?'timeline-done':''}"><div class="timeline-clock">${escapeHTML(item.time)}</div><div class="timeline-marker task-marker">${item.done?'✓':'•'}</div><div class="timeline-content"><span class="timeline-kind">TAREA ${item.done?'· COMPLETADA':'· PENDIENTE'}</span><strong>${escapeHTML(item.title)}</strong></div></div>`).join('')}if(untimedTasks.length){html+=`<div class="timeline-untimed-heading">Tareas sin hora</div>`+untimedTasks.map(item=>`<div class="timeline-item ${item.done?'timeline-done':''}"><div class="timeline-clock timeline-no-time">—</div><div class="timeline-marker task-marker">${item.done?'✓':'•'}</div><div class="timeline-content"><span class="timeline-kind">TAREA ${item.done?'· COMPLETADA':'· PENDIENTE'}</span><strong>${escapeHTML(item.title)}</strong></div></div>`).join('')}if(!html)html='<div class="timeline-empty">Todavía no hay citas ni tareas para este día. Añade una cita o crea una tarea para organizar tu jornada.</div>';host.innerHTML=html}
function closeAppointmentForm(){const f=$('#appointmentForm');f.classList.add('hidden');$('#toggleAppointmentForm').setAttribute('aria-expanded','false');$('#toggleAppointmentForm').textContent='+ Añadir cita';f.reset();$('#appointmentDate').value=selected;$('#appointmentEndDate').value=selected;$('#appointmentStart').value='09:00';$('#appointmentEnd').value='09:30';$('#appointmentMode').value='timed';$('#appointmentEndDateWrap').classList.add('hidden');$('#appointmentStart').closest('label').classList.remove('hidden');$('#appointmentEnd').closest('label').classList.remove('hidden');$('#appointmentReminder').value='15';updateAppointmentMode()}
function openAppointmentForm(){const f=$('#appointmentForm');f.classList.remove('hidden');$('#appointmentDate').value=selected;$('#toggleAppointmentForm').setAttribute('aria-expanded','true');$('#toggleAppointmentForm').textContent='Cerrar';$('#appointmentTitle').focus();f.scrollIntoView({behavior:'smooth',block:'nearest'})}
function updateAppointmentMode(){const mode=$('#appointmentMode').value;const startLabel=$('#appointmentStart').closest('label'),endLabel=$('#appointmentEnd').closest('label'),endDateWrap=$('#appointmentEndDateWrap');startLabel.classList.toggle('hidden',mode==='allDay');endLabel.classList.toggle('hidden',mode==='allDay');endDateWrap.classList.toggle('hidden',mode!=='multi');$('#appointmentReminder').disabled=mode==='allDay'}
function bindAppointments(){const toggle=$('#toggleAppointmentForm'),form=$('#appointmentForm');toggle.addEventListener('click',()=>form.classList.contains('hidden')?openAppointmentForm():closeAppointmentForm());$('#cancelAppointmentForm').addEventListener('click',closeAppointmentForm);$('#appointmentMode').addEventListener('change',updateAppointmentMode);form.addEventListener('submit',async e=>{e.preventDefault();const title=$('#appointmentTitle').value.trim(),date=$('#appointmentDate').value,mode=$('#appointmentMode').value;let start=$('#appointmentStart').value,end=$('#appointmentEnd').value,endDate=date;if(!title||!date){toast('Completa el nombre y la fecha');return}if(mode==='allDay'){start='';end='';endDate=date}else if(mode==='24h'){if(!start){toast('Indica la hora de inicio');return}const next=new Date(date+'T12:00:00');next.setDate(next.getDate()+1);endDate=iso(next);end=start}else if(mode==='multi'){endDate=$('#appointmentEndDate').value;if(!endDate||endDate<date){toast('La fecha final debe ser igual o posterior a la inicial');return}if(!start||!end){toast('Indica las horas de inicio y fin');return}if(endDate===date&&end<=start){toast('Si termina otro día, selecciona la fecha final');return}}else{if(!start||!end){toast('Indica la hora de inicio y fin');return}if(end<=start){toast('La hora de finalización debe ser posterior al inicio');$('#appointmentEnd').focus();return}}const reminder=mode==='allDay'?0:(Number($('#appointmentReminder').value)||0);const appt={id:appointmentId(),title,date,endDate,mode,start,end,location:$('#appointmentLocation').value.trim(),notes:$('#appointmentNotes').value.trim(),reminder,status:'pending',reminderSentAt:null,createdAt:new Date().toISOString()};data.appointments ||= [];data.appointments.push(appt);selected=date;viewMonth=new Date(date+'T12:00:00');save();renderAll();closeAppointmentForm();renderAppointments();toast('Cita guardada');if(reminder>0&&'Notification'in window&&Notification.permission==='default'){try{const permission=await Notification.requestPermission();if(permission==='granted')toast('Avisos activados en este navegador')}catch{}}});updateAppointmentMode()}
function checkAppointmentReminders(){if(!Array.isArray(data.appointments))return;const now=new Date();let changed=false;for(const a of data.appointments){if(a.status!=='pending'||a.mode==='allDay'||!Number(a.reminder)||a.reminderSentAt)continue;const start=new Date(`${a.date}T${a.start}:00`);const diff=start.getTime()-now.getTime();if(diff<=Number(a.reminder)*60000&&diff>0){const message=`${a.title} empieza a las ${a.start}${a.location?' · '+a.location:''}`;if('Notification'in window&&Notification.permission==='granted'){try{new Notification('TOTY Planner · Próxima cita',{body:message,tag:a.id})}catch{toast('Próxima cita: '+message)}}else{toast('Próxima cita: '+message)}a.reminderSentAt=now.toISOString();changed=true}}if(changed)save()}
function bindText(id,key){$(id).addEventListener('input',e=>{dayData()[key]=e.target.value;save()})}
function renderHabits(){let h=dayData().habits;$$('[data-habit]').forEach(el=>el.checked=!!h[el.dataset.habit]);let n=Object.values(h).filter(Boolean).length;const total=5;$('#habitCount').textContent=`${n}/${total}`;$('#habitProgress').style.width=(n/total*100)+'%';$('#habitMessage').textContent=n===total?'¡Has completado todos tus hábitos de hoy!':n===0?'Cada pequeño hábito cuenta.':`Has completado ${n} de ${total} hábitos. ¡Sigue así!`}
const CATEGORIES=['Alimentación','Transporte','Hogar','Salud','Ocio','Suscripciones','Compras','Educación','Otros'];
function categoryOptions(current){return CATEGORIES.map(c=>`<option value="${c}" ${c===current?'selected':''}>${c}</option>`).join('')}
function normalizeExpense(e){if(!e.category)e.category='Otros';if(!e.type)e.type='expense';return e}
function renderExpenses(){const ex=dayData().expenses;ex.forEach(normalizeExpense);$('#expenseList').innerHTML=ex.length?ex.map((e,i)=>`<div class="expense-row movement-row"><div class="movement-fields"><input data-exp-name="${i}" value="${escapeHTML(e.name||'')}" placeholder="Concepto (ej. compra semanal)" aria-label="Concepto del movimiento"><div class="movement-meta"><select data-exp-type="${i}" aria-label="Tipo"><option value="expense" ${e.type!=='income'?'selected':''}>Gasto</option><option value="income" ${e.type==='income'?'selected':''}>Ingreso</option></select><select data-exp-category="${i}" aria-label="Categoría">${categoryOptions(e.category)}</select></div></div><input class="amount" data-exp-amount="${i}" type="number" min="0" step="0.01" inputmode="decimal" value="${e.amount??''}" placeholder="0,00" aria-label="Importe en euros"><button class="delete-expense" data-exp-del="${i}" aria-label="Eliminar movimiento">×</button></div>`).join(''):'<div class="empty-expenses">Todavía no has añadido movimientos para este día.</div>';
$$('[data-exp-name]').forEach(el=>el.addEventListener('input',()=>{dayData().expenses[+el.dataset.expName].name=el.value;save();renderHistoryOnly()}));
$$('[data-exp-amount]').forEach(el=>el.addEventListener('input',()=>{dayData().expenses[+el.dataset.expAmount].amount=el.value;save();renderHistoryOnly()}));
$$('[data-exp-type]').forEach(el=>el.addEventListener('change',()=>{dayData().expenses[+el.dataset.expType].type=el.value;save();renderStats()}));
$$('[data-exp-category]').forEach(el=>el.addEventListener('change',()=>{dayData().expenses[+el.dataset.expCategory].category=el.value;save();renderStats()}));
$$('[data-exp-del]').forEach(el=>el.addEventListener('click',()=>{dayData().expenses.splice(+el.dataset.expDel,1);save();renderExpenses()}))}
function monthMovements(monthKey){return Object.entries(data.days).filter(([k])=>k.startsWith(monthKey)).flatMap(([date,d])=>(d.expenses||[]).map((raw,i)=>{const e=normalizeExpense(raw);return {...e,date,index:i}})).sort((a,b)=>b.date.localeCompare(a.date)||b.index-a.index)}
function renderHistoryOnly(items=monthMovements(selected.slice(0,7)),period='month'){const label=period==='year'?'este año':'este mes';$('#historyCount').textContent=`${items.length} ${items.length===1?'movimiento':'movimientos'}`;$('#historyHeading').textContent=period==='year'?'Historial del año':'Historial del mes';$('#movementHistory').innerHTML=items.length?items.map(e=>`<div class="history-row"><div class="history-icon ${e.type==='income'?'history-income':''}">${e.type==='income'?'↙':'↗'}</div><div class="history-copy"><strong>${escapeHTML(e.name||'Sin concepto')}</strong><small>${escapeHTML(pretty(e.date,{day:'numeric',month:'short',year:'numeric'}))} · ${escapeHTML(e.category||'Otros')}</small></div><strong class="history-amount ${e.type==='income'?'income-text':'expense-text'}">${e.type==='income'?'+':'−'}${money(e.amount)}</strong></div>`).join(''):`<div class="empty-expenses">No hay movimientos registrados ${label}.</div>`}
function yearMovements(year){return Object.entries(data.days).filter(([k])=>k.startsWith(String(year))).flatMap(([date,d])=>(d.expenses||[]).map((raw,i)=>{const e=normalizeExpense(raw);return {...e,date,index:i}})).sort((a,b)=>b.date.localeCompare(a.date)||b.index-a.index)}
function renderFinanceCharts(items,total,budget,periodLabel='mensual'){const spendBy={};items.filter(e=>e.type!=='income').forEach(e=>{const c=e.category||'Otros';spendBy[c]=(spendBy[c]||0)+(Number(e.amount)||0)});const cats=Object.entries(spendBy).sort((a,b)=>b[1]-a[1]);const max=Math.max(1,...cats.map(x=>x[1]));$('#categoryChart').innerHTML=cats.length?cats.map(([name,val])=>`<div class="chart-row"><div class="chart-label"><span>${escapeHTML(name)}</span><strong>${money(val)}</strong></div><div class="chart-track"><div class="chart-fill" style="width:${val/max*100}%"></div></div></div>`).join(''):'<div class="empty-expenses">Añade gastos para ver el gráfico por categorías.</div>';const pct=budget>0?Math.min(100,total/budget*100):0;$('#budgetComparison').innerHTML=`<div class="comparison-numbers"><div><span>Presupuesto</span><strong>${money(budget)}</strong></div><div><span>Gasto real</span><strong class="expense-text">${money(total)}</strong></div></div><div class="chart-track comparison-track"><div class="chart-fill ${total>budget&&budget>0?'over-budget':''}" style="width:${pct}%"></div></div><p class="muted">${budget>0?(total>budget?`Has superado el presupuesto en ${money(total-budget)}.`:`Has utilizado el ${Math.round(total/budget*100)}% del presupuesto.`):`Introduce un presupuesto ${periodLabel==='anual'?'anual':'mensual'} para comparar el gasto real.`}</p>`}
function renderDailySummary(){const d=dayData();const done=d.checks.filter(Boolean).length;const total=d.priorities.length;const sportCount=(data.sports||[]).filter(x=>x.date===selected).length;const movements=(d.expenses||[]).map(normalizeExpense);const spent=movements.filter(e=>e.type!=='income').reduce((s,e)=>s+(Number(e.amount)||0),0);const income=movements.filter(e=>e.type==='income').reduce((s,e)=>s+(Number(e.amount)||0),0);$('#summaryDate').textContent=selected===iso(today)?'Hoy':pretty(selected,{day:'numeric',month:'short'});$('#summaryTasks').textContent=`${done}/${total}`;$('#summaryTasksNote').textContent=total===done?'todo listo':`${Math.max(0,total-done)} por completar`;$('#summaryHabits').textContent=String(sportCount);$('#summaryHabitsNote').textContent=sportCount===1?'sesión registrada':'sesiones registradas';$('#summaryBalance').textContent=money(income-spent);$('#summaryBalance').style.color=income-spent<0?'var(--danger)':'var(--success)';$('#summaryBalanceNote').textContent=income-spent<0?'gasto neto del día':'balance neto del día';const next=(data.appointments||[]).filter(a=>a.date<=selected&&(a.endDate||a.date)>=selected&&a.status==='pending').sort((a,b)=>(a.start||'').localeCompare(b.start||''))[0];const nextEl=$('#nextAppointmentSummary');if(nextEl){if(next){nextEl.classList.remove('hidden');nextEl.innerHTML=`<span class="next-time">${escapeHTML(next.mode==='allDay'?'Todo el día':next.start||'')}</span><span>Próxima cita: <strong>${escapeHTML(next.title)}</strong>${next.location?' · '+escapeHTML(next.location):''}</span>`}else{nextEl.classList.add('hidden');nextEl.textContent=''}}}
function renderStats(){let taskData=dayData();let completed=taskData.checks.filter(Boolean).length;$('#priorityCount').textContent=`${completed}/${taskData.priorities.length}`;const monthKey=selected.slice(0,7);const year=balanceYear;const items=balancePeriod==='year'?yearMovements(year):monthMovements(monthKey);const labelDate=balancePeriod==='year'?String(year):new Date(selected+'T12:00:00').toLocaleDateString('es-ES',{month:'long',year:'numeric'});$('#balanceMonth').textContent=balancePeriod==='year'?`Resumen de enero a diciembre de ${year}`:labelDate;const monthBudget=Number(data.budgets[monthKey])||0;const budget=balancePeriod==='year'?Object.entries(data.budgets||{}).filter(([k])=>k.startsWith(String(year))).reduce((sum,[,v])=>sum+(Number(v)||0),0):monthBudget;$('#monthlyBudget').value=balancePeriod==='year'?budget:(data.budgets[monthKey]??'');$('#monthlyBudget').disabled=balancePeriod==='year';$('#budgetHeading').textContent=balancePeriod==='year'?'PRESUPUESTO TOTAL DEL AÑO (€)':'PRESUPUESTO MENSUAL (€)';$('#categoryEyebrow').textContent=balancePeriod==='year'?'ANÁLISIS ANUAL':'ANÁLISIS MENSUAL';$('#comparisonEyebrow').textContent=balancePeriod==='year'?'PRESUPUESTO ANUAL VS. REAL':'PRESUPUESTO VS. REAL';$('#comparisonHeading').textContent=balancePeriod==='year'?'Comparación anual':'Comparación mensual';let total=items.filter(e=>e.type!=='income').reduce((sum,e)=>sum+(Number(e.amount)||0),0);let income=items.filter(e=>e.type==='income').reduce((sum,e)=>sum+(Number(e.amount)||0),0);$('#monthExpenses').textContent=money(total);$('#monthIncome').textContent=money(income);$('#availableAmount').textContent=money(budget-total);$('#availableAmount').style.color=budget-total<0?'var(--danger)':'var(--success)';$('#netAmount').textContent=money(income-total);$('#netAmount').style.color=income-total<0?'var(--danger)':'var(--success)';const pct=budget>0?Math.min(100,total/budget*100):0;$('#budgetProgress').style.width=pct+'%';$('#budgetProgress').classList.toggle('over-budget',budget>0&&total>budget);$('#budgetMessage').textContent=budget<=0?`Define tu presupuesto ${balancePeriod==='year'?'mensual para que se sume al total anual':'para calcular lo disponible'}.`:total>budget?`Has superado el presupuesto en ${money(total-budget)}.`:`Has gastado ${Math.round(total/budget*100)}% del presupuesto; quedan ${money(budget-total)}.`;renderFinanceCharts(items,total,budget,balancePeriod==='year'?'anual':'mensual');renderHistoryOnly(items,balancePeriod);renderDailySummary()}

function resolvedDayType(date,override='auto'){if(override&&override!=='auto')return override;const day=new Date(date+'T12:00:00').getDay();return day===0||day===6?'weekend':'laborable'}
const shiftNames={'M':'Mañana','T':'Tarde','COCHE':'Cocheras','C/M':'Calle de mañana','C/T':'Calle de tarde','FRANQ':'Franqueos','D':'Fiesta pedida','V':'Vacaciones','DHA':'Día por horas acumuladas'};
const shiftColors={'M':'#d1fae5','T':'#ffedd5','COCHE':'#dbeafe','C/M':'#cffafe','C/T':'#fce7f3','FRANQ':'#ede9fe','D':'#f3f4f6','V':'#fde68a','DHA':'#fecaca'};
function shiftSchedule(code,date,override='auto'){const type=resolvedDayType(date,override);const schedules={'M':{laborable:['05:25','13:25'],weekend:['06:00','14:30'],holiday:['06:00','14:30']},'T':{laborable:['15:00','23:00'],weekend:['14:30','23:00'],holiday:['14:30','23:00']},'COCHE':{laborable:['08:00','15:00'],weekend:null,holiday:null},'C/M':{laborable:['06:30','14:15'],weekend:['06:30','14:15'],holiday:['06:30','14:15']},'C/T':{laborable:['14:15','22:00'],weekend:['14:15','22:00'],holiday:['14:15','22:00']}};if(['FRANQ','D','V','DHA'].includes(code))return {label:'Todo el día',hours:0,type};const pair=schedules[code]?.[type];return pair?{label:pair.join('–'),hours:(Number(pair[1].split(':')[0])*60+Number(pair[1].split(':')[1])-(Number(pair[0].split(':')[0])*60+Number(pair[0].split(':')[1])))/60,type}:{label:'Sin horario: solo laborables',hours:0,type}}
function renderWorkCalendar(){const y=workViewMonth.getFullYear(),m=workViewMonth.getMonth();$('#workMonthTitle').textContent=workViewMonth.toLocaleDateString('es-ES',{month:'long',year:'numeric'});const first=(new Date(y,m,1).getDay()+6)%7,count=new Date(y,m+1,0).getDate(),prevCount=new Date(y,m,0).getDate();let html='';for(let i=0;i<42;i++){let n=i-first+1,d,outside=false;if(n<1){d=new Date(y,m-1,prevCount+n);outside=true}else if(n>count){d=new Date(y,m+1,n-count);outside=true}else d=new Date(y,m,n);const key=iso(d),shift=data.days[key]?.shift||'';const cls=shift?' has-shift shift-day-'+shift.replace('/','').replace(' ','') : '';html+=`<button type="button" class="calendar-day${outside?' outside':''}${key===iso(today)?' today':''}${key===selected?' selected':''}${cls}" data-work-date="${key}" ${shift?`style="--shift-bg:${shiftColors[shift]||'#e5e7eb'}"`:''} aria-label="${escapeHTML(pretty(key))}${shift?', turno '+shift:''}"><span>${d.getDate()}</span>${shift?`<small>${escapeHTML(shift)}</small>`:''}</button>`}$('#workCalendarGrid').innerHTML=html;$$('[data-work-date]').forEach(b=>b.addEventListener('click',()=>selectDate(b.dataset.workDate)));renderWorkEditor();renderWorkStats()}
function renderWorkEditor(){const d=dayData();$('#workSelectedDate').textContent=pretty(selected);$('#shiftSelect').value=d.shift||'';$('#workDayType').value=d.dayType||'auto';const badge=$('#shiftBadge');badge.textContent=d.shift||'Sin turno';badge.className='shift-badge'+(d.shift?' shift-'+d.shift.replace('/','').replace(' ',''):'');const info=d.shift?shiftSchedule(d.shift,selected,d.dayType||'auto'):{label:'Selecciona un turno para ver su horario.',hours:0};$('#shiftHours').textContent=d.shift?`${shiftNames[d.shift]} · ${info.label}${info.type==='weekend'?' · fin de semana':info.type==='holiday'?' · festivo':' · laborable'}`:info.label;}
function periodDatesForWork(){if(workPeriod==='year')return Object.keys(data.days).filter(k=>k.startsWith(String(workYear)));const monthKey=`${workViewMonth.getFullYear()}-${String(workViewMonth.getMonth()+1).padStart(2,'0')}`;return Object.keys(data.days).filter(k=>k.startsWith(monthKey))}
function renderWorkStats(){const keys=periodDatesForWork(),counts={};let hours=0;for(const date of keys){const d=data.days[date],code=d.shift;if(!code)continue;counts[code]=(counts[code]||0)+1;hours+=shiftSchedule(code,date,d.dayType||'auto').hours||0}const order=['M','T','COCHE','C/M','C/T','FRANQ','D','V','DHA'];$('#workStatsGrid').innerHTML=order.map(code=>`<div class="work-stat"><span class="shift-badge shift-${code.replace('/','').replace(' ','')}">${code}</span><div><strong>${counts[code]||0}</strong><small>${shiftNames[code]}</small></div></div>`).join('');$('#workHoursTotal').textContent=`${Math.floor(hours)} h${Math.round((hours%1)*60)?' '+Math.round((hours%1)*60)+' min':''}`;$$('[data-work-period]').forEach(b=>b.classList.toggle('active',b.dataset.workPeriod===workPeriod));$('#workYear').value=String(workYear)}
function setupYearSelect(id,initial,change){const el=$(id);if(!el)return;el.innerHTML='';for(let y=today.getFullYear()-5;y<=today.getFullYear()+5;y++){const o=document.createElement('option');o.value=String(y);o.textContent=String(y);el.appendChild(o)}el.value=String(initial);el.addEventListener('change',()=>change(Number(el.value)))}
function initWork(){setupYearSelect('#workYear',workYear,y=>{workYear=y;renderWorkStats()});setupYearSelect('#balanceYear',balanceYear,y=>{balanceYear=y;renderStats()});$('#workPrevMonth').addEventListener('click',()=>{workViewMonth=new Date(workViewMonth.getFullYear(),workViewMonth.getMonth()-1,1);renderWorkCalendar()});$('#workNextMonth').addEventListener('click',()=>{workViewMonth=new Date(workViewMonth.getFullYear(),workViewMonth.getMonth()+1,1);renderWorkCalendar()});$('#shiftSelect').addEventListener('change',e=>{const code=e.target.value;const d=dayData();d.shift=code;save();renderWorkCalendar();const type=resolvedDayType(selected,d.dayType||'auto');if(code==='COCHE'&&type!=='laborable'){toast('Turno COCHE guardado. Este día está marcado como '+(type==='weekend'?'fin de semana':'festivo')+'. Si es laborable por excepción, cambia «Tipo de día» a Laborable.')}else toast(code?'Turno guardado correctamente':'Turno eliminado')});$('#workDayType').addEventListener('change',e=>{dayData().dayType=e.target.value;save();renderWorkEditor();renderWorkStats()});$('#clearShift').addEventListener('click',()=>{dayData().shift='';save();renderWorkCalendar();toast('Turno eliminado')});$$('[data-work-period]').forEach(b=>b.addEventListener('click',()=>{workPeriod=b.dataset.workPeriod;renderWorkStats()}));$$('[data-balance-period]').forEach(b=>b.addEventListener('click',()=>{balancePeriod=b.dataset.balancePeriod;$$('[data-balance-period]').forEach(x=>x.classList.toggle('active',x===b));renderStats()}));}
function renderAll(){renderCalendar();renderDay();renderWorkCalendar();if($('#deporte'))renderSport()}
$('#prevMonth').addEventListener('click',()=>{viewMonth=new Date(viewMonth.getFullYear(),viewMonth.getMonth()-1,1);renderCalendar()});$('#nextMonth').addEventListener('click',()=>{viewMonth=new Date(viewMonth.getFullYear(),viewMonth.getMonth()+1,1);renderCalendar()});$('#todayBtn').addEventListener('click',()=>selectDate(iso(today)));
bindAppointments();
$$('.tab').forEach(b=>b.addEventListener('click',()=>openTab(b.dataset.tab)));$$('[data-summary-tab]').forEach(b=>b.addEventListener('click',()=>openTab(b.dataset.summaryTab)));
bindText('#dailyNotes','notes');bindText('#quickNotes','quick');bindText('#workout','workout');bindText('#workoutFeeling','feeling');bindText('#workoutExtra','extra');
$$('[data-habit]').forEach(el=>el.addEventListener('change',()=>{dayData().habits[el.dataset.habit]=el.checked;save();renderHabits()}));
function addDailyTask(){const d=dayData();d.priorities.push('');d.checks.push(false);d.taskTimes.push('');save();renderDay();const fields=$$('#priorityList input[data-priority]');const last=fields[fields.length-1];if(last){last.focus();last.scrollIntoView({behavior:'smooth',block:'nearest'});}}
const addTaskButton=$('#addTask');if(addTaskButton)addTaskButton.addEventListener('click',addDailyTask);
$('#monthlyBudget').addEventListener('input',e=>{if(balancePeriod==='year')return;data.budgets[selected.slice(0,7)]=e.target.value;save()});$('#addExpense').addEventListener('click',()=>{dayData().expenses.push({name:'',amount:'',category:'Otros',type:'expense'});save();renderExpenses();let fields=$$('#expenseList input[data-exp-name]');fields[fields.length-1]?.focus()});
$('#exportBtn').addEventListener('click',downloadBackup);$('#importBtn').addEventListener('click',()=>$('#importFile').click());$('#importFile').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{const imported=JSON.parse(await f.text());if(!imported.days||!imported.budgets)throw new Error('Formato');imported.appointments ||= [];data=imported;save();renderAll();setBackupStatus('Copia importada y guardada en este dispositivo. Descarga otra copia externa cuando quieras.');toast('Copia restaurada correctamente')}catch{toast('No se pudo leer esa copia de seguridad')}e.target.value=''});$('#printBtn').addEventListener('click',()=>window.print());$('#clearDayBtn').addEventListener('click',()=>{if(confirm('¿Vaciar notas, hábitos, tareas, gastos y citas de '+pretty(selected)+'?')){delete data.days[selected];data.appointments=(data.appointments||[]).filter(a=>a.date!==selected);save();renderDay();renderWorkCalendar();toast('Día vaciado')}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;$('#installBtn').classList.remove('hidden')});$('#installBtn').addEventListener('click',async()=>{if(!deferredInstall){toast('Usa el menú del navegador y elige “Añadir a pantalla de inicio”');return}deferredInstall.prompt();await deferredInstall.userChoice;deferredInstall=null;$('#installBtn').classList.add('hidden')});
